import{_ as n,o as e,c as t,a0 as l}from"./chunks/framework.D7EjqxMK.js";const d=JSON.parse('{"title":"LLM 与 Agent 的关系","description":"","frontmatter":{},"headers":[],"relativePath":"06-agent/01_基础概念/02_LLM与Agent的关系.md","filePath":"06-agent/01_基础概念/02_LLM与Agent的关系.md"}'),s={name:"06-agent/01_基础概念/02_LLM与Agent的关系.md"};function r(i,a,o,g,p,h){return e(),t("div",null,[...a[0]||(a[0]=[l(`<h1 id="llm-与-agent-的关系" tabindex="-1">LLM 与 Agent 的关系 <a class="header-anchor" href="#llm-与-agent-的关系" aria-label="Permalink to &quot;LLM 与 Agent 的关系&quot;">​</a></h1><blockquote><p><strong>在知识图谱中的位置</strong>：模块一 · 01_基础概念 · 第 2 节 <strong>难度</strong>：⭐⭐⭐ | <strong>前置知识</strong>：基础 LLM 知识</p></blockquote><hr><h2 id="_1-概述" tabindex="-1">1. 概述 <a class="header-anchor" href="#_1-概述" aria-label="Permalink to &quot;1. 概述&quot;">​</a></h2><p>LLM（大语言模型）是 Agent 的「大脑」，但 LLM ≠ Agent。理解两者的关系是掌握 Agent 技术的关键。</p><hr><h2 id="_2-核心概念" tabindex="-1">2. 核心概念 <a class="header-anchor" href="#_2-核心概念" aria-label="Permalink to &quot;2. 核心概念&quot;">​</a></h2><h3 id="_2-1-llm-是什么" tabindex="-1">2.1 LLM 是什么 <a class="header-anchor" href="#_2-1-llm-是什么" aria-label="Permalink to &quot;2.1 LLM 是什么&quot;">​</a></h3><p>大语言模型本质是一个<strong>概率文本生成器</strong>：给定上下文输入，输出下一个词的概率分布。</p><p><strong>局限</strong>：</p><ul><li>知识截止于训练数据，无法获取实时信息</li><li>无法直接操作外部系统</li><li>没有持久记忆（仅靠上下文窗口）</li><li>可能有幻觉</li></ul><h3 id="_2-2-agent-llm-工具-记忆-规划-反思" tabindex="-1">2.2 Agent = LLM + 工具 + 记忆 + 规划 + 反思 <a class="header-anchor" href="#_2-2-agent-llm-工具-记忆-规划-反思" aria-label="Permalink to &quot;2.2 Agent = LLM + 工具 + 记忆 + 规划 + 反思&quot;">​</a></h3><h3 id="_2-3-llm-→-agent-的跃迁路径" tabindex="-1">2.3 LLM → Agent 的跃迁路径 <a class="header-anchor" href="#_2-3-llm-→-agent-的跃迁路径" aria-label="Permalink to &quot;2.3 LLM → Agent 的跃迁路径&quot;">​</a></h3><p>| 阶段 | 描述 | 技术要点 | |--|-|--|- | | 纯 LLM | 问答 | Prompt Engineering | | + 工具调用 | Function Calling | 结构化输出 | | + RAG | 知识库问答 | 向量检索 | | + 规划 | 多步推理 | ReAct / CoT | | + 记忆 | 跨会话 | 向量DB + 摘要 | | + 反思 | 自我改进 | Reflexion | | = Agent | 自主执行任务 | 完整四模块 |</p><hr><h2 id="_3-技术原理" tabindex="-1">3. 技术原理 <a class="header-anchor" href="#_3-技术原理" aria-label="Permalink to &quot;3. 技术原理&quot;">​</a></h2><h3 id="_3-1-llm-作为-agent-大脑的三个角色" tabindex="-1">3.1 LLM 作为 Agent 大脑的三个角色 <a class="header-anchor" href="#_3-1-llm-作为-agent-大脑的三个角色" aria-label="Permalink to &quot;3.1 LLM 作为 Agent 大脑的三个角色&quot;">​</a></h3><p>| 角色 | 能力 | 要求 | |--|-|--|- | | <strong>意图理解</strong> | 理解用户目标 | 通用理解力 | | <strong>推理决策</strong> | 决定调用哪个工具 | Function Calling | | <strong>结果评估</strong> | 判断是否继续或停止 | 逻辑推理 |</p><h3 id="_3-2-关键转折点" tabindex="-1">3.2 关键转折点 <a class="header-anchor" href="#_3-2-关键转折点" aria-label="Permalink to &quot;3.2 关键转折点&quot;">​</a></h3><p>| 时间 | 事件 | 意义 | |--|-|--|- | | 2023.06 | ChatGPT Plugins | 首次工具调用实验 | | 2023.11 | GPT-4 Function Calling | 结构化 JSON 输出 | | 2024.05 | GPT-4o | 多模态 + 高效 FC | | 2024.12 | Claude 3.5 + Computer Use | LLM 直接操作电脑 | | 2025.03 | OpenAI Agents SDK | 官方轻量 Agent SDK | | 2025 | LLM-as-Agent 趋势 | 框架退场，模型即 Agent |</p><h3 id="_3-3-llm-as-agent-趋势-2025-2026" tabindex="-1">3.3 LLM-as-Agent 趋势（2025-2026） <a class="header-anchor" href="#_3-3-llm-as-agent-趋势-2025-2026" aria-label="Permalink to &quot;3.3 LLM-as-Agent 趋势（2025-2026）&quot;">​</a></h3><p>OpenAI 和 Anthropic 正在推动<strong>不需要框架的 Agent</strong>：</p><ul><li><strong>OpenAI Agents SDK</strong> — 官方轻量 SDK，Agent 即概念</li><li><strong>Claude Computer Use</strong> — Claude 直接操作电脑界面</li><li><strong>框架退场</strong> — 框架简化为薄封装</li></ul><hr><h2 id="_4-实践指南" tabindex="-1">4. 实践指南 <a class="header-anchor" href="#_4-实践指南" aria-label="Permalink to &quot;4. 实践指南&quot;">​</a></h2><h3 id="_4-1-模型选择决策树" tabindex="-1">4.1 模型选择决策树 <a class="header-anchor" href="#_4-1-模型选择决策树" aria-label="Permalink to &quot;4.1 模型选择决策树&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>你需要 Agent？</span></span>
<span class="line"><span>  ├── 需要 Function Calling？</span></span>
<span class="line"><span>  │   ├── GPT-4o（最成熟）</span></span>
<span class="line"><span>  │   ├── Claude 3.5 Sonnet（性价比）</span></span>
<span class="line"><span>  │   └── Claude 3.5 Opus（推理最强）</span></span>
<span class="line"><span>  ├── 需要超长上下文？</span></span>
<span class="line"><span>  │   ├── Claude 3.5 Sonnet（200K）</span></span>
<span class="line"><span>  │   └── Gemini 2.0（1M）</span></span>
<span class="line"><span>  ├── 需要自部署？</span></span>
<span class="line"><span>  │   ├── DeepSeek-R1（开源推理）</span></span>
<span class="line"><span>  │   └── Llama 3.1（开源通用）</span></span>
<span class="line"><span>  └── 需要多模态？</span></span>
<span class="line"><span>      └── GPT-4o / Claude 3.5 / Gemini 2.0</span></span></code></pre></div><h3 id="_4-2-最佳实践" tabindex="-1">4.2 最佳实践 <a class="header-anchor" href="#_4-2-最佳实践" aria-label="Permalink to &quot;4.2 最佳实践&quot;">​</a></h3><ul><li><strong>Function Calling 温度设 0.1</strong> — 确保结构输出稳定</li><li><strong>工具描述 &gt; 工具名</strong> — LLM 看描述决定调用</li><li><strong>返回格式严格</strong> — JSON Schema 定义工具参数</li><li><strong>多轮对话保留上下文</strong> — 每步结果追加到消息</li></ul><h3 id="_4-3-常见陷阱" tabindex="-1">4.3 常见陷阱 <a class="header-anchor" href="#_4-3-常见陷阱" aria-label="Permalink to &quot;4.3 常见陷阱&quot;">​</a></h3><ul><li><strong>混淆 RAG 和 Agent</strong> — RAG 是检索增强，不是 Agent</li><li><strong>过度使用 LLM 做决策</strong> — 能用代码判断就不用 LLM</li><li><strong>忽略成本</strong> — 每步工具调用 = 一次 API 费用</li></ul><hr><h2 id="_5-参考资料" tabindex="-1">5. 参考资料 <a class="header-anchor" href="#_5-参考资料" aria-label="Permalink to &quot;5. 参考资料&quot;">​</a></h2><ul><li><a href="https://platform.openai.com/docs/guides/function-calling" target="_blank" rel="noreferrer">OpenAI Function Calling 文档</a></li><li><a href="https://cj.sina.com.cn/articles/view/7857201856/1d45362c001902swcu" target="_blank" rel="noreferrer">2025 Agent 综述 | 55页长文系统梳理</a></li></ul><hr><h2 id="_6-学习路径" tabindex="-1">6. 学习路径 <a class="header-anchor" href="#_6-学习路径" aria-label="Permalink to &quot;6. 学习路径&quot;">​</a></h2><ol><li><strong>Level 1</strong> — 写一个 Function Calling 示例</li><li><strong>Level 2</strong> — 实现 3 个工具的协作调用</li><li><strong>Level 3</strong> — 对比 GPT-4o vs Claude 的工具调用效果</li><li><strong>Level 4</strong> — 理解 LLM-as-Agent 范式</li><li><strong>Level 5</strong> — 阅读 OpenAI Agents SDK 源码</li></ol>`,37)])])}const u=n(s,[["render",r]]);export{d as __pageData,u as default};
